void need(bool b,const char* m){if(!b)throw std::runtime_error(m);}
template<class W>W* widget(QObject& d,const char* name){auto* w=d.findChild<W*>(name);need(w,name);return w;}
QAction* action(MainWindow& w,const char* name){return widget<QAction>(w,name);}
QPushButton* button(QDialog& d,const char* name){return widget<QPushButton>(d,name);}
